<?php require 'config.php'; require_login(); $uid=$_SESSION['uid'];
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf();
  if (($_POST['action'] ?? '')==='delete') $pdo->prepare('DELETE FROM assets WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]);
  else { $n=mb_substr(trim($_POST['name'] ?? ''),0,80); $v=(float)($_POST['value'] ?? 0); if ($n===''||$v<=0) flash('Enter a name and a value above zero.'); else { $pdo->prepare('INSERT INTO assets(user_id,name,kind,value) VALUES(?,?,?,?)')->execute([$uid,$n,($_POST['kind'] ?? '')==='liability'?'liability':'asset',$v]); flash('Saved.'); } }
  header('Location: networth.php'); exit; }
$n=snapshot_networth($pdo,$uid); $a=$pdo->prepare('SELECT * FROM assets WHERE user_id=? ORDER BY kind,value DESC'); $a->execute([$uid]); $items=$a->fetchAll();
$h=$pdo->prepare('SELECT * FROM networth_history WHERE user_id=? ORDER BY snap_date DESC LIMIT 24'); $h->execute([$uid]); $hist=array_reverse($h->fetchAll()); $mx=max(1,...array_map(fn($r)=>abs($r['assets']-$r['liabilities']),$hist ?: [['assets'=>1,'liabilities'=>0]]));
page_head('Net worth'); ?>
<h1>Net worth</h1>
<div class="grid"><div class="card stat"><span>Assets</span><b class="pos"><?= money($n['assets']) ?></b></div><div class="card stat"><span>Liabilities</span><b class="neg"><?= money($n['liabilities']) ?></b></div><div class="card stat"><span>Net worth</span><b class="<?= $n['net']<0?'neg':'' ?>"><?= money($n['net']) ?></b></div></div>
<p class="note">Includes your account balances and recorded debts automatically. Add anything else you own or owe below.</p>
<div class="card scroll"><table><tr><th>Item</th><th>Kind</th><th class="r">Value</th><th></th></tr>
<?php foreach ($items as $i): ?><tr><td><?= e($i['name']) ?></td><td><?= e($i['kind']) ?></td><td class="r"><?= money($i['value']) ?></td><td><form method="post" data-confirm="Remove?"><?= csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $i['id'] ?>"><button class="link">Delete</button></form></td></tr><?php endforeach; if (!$items) echo '<tr><td colspan="4">Nothing added yet (land, a phone, a car, money owed to others...).</td></tr>'; ?></table></div>
<form method="post" class="card narrow"><h2 style="margin-top:0">Add asset or liability</h2><?= csrf() ?><label>Name<input name="name" required maxlength="80"></label><label>Kind<select name="kind"><option value="asset">Asset (I own)</option><option value="liability">Liability (I owe)</option></select></label><label>Value<input type="number" step="0.01" min="0.01" name="value" required></label><button class="btn">Add</button></form>
<h2>Net-worth history</h2><?php if (!is_premium()): ?><div class="card">History tracking is a Premium feature. <a href="plans.php">See plans</a></div><?php else: ?>
<div class="card scroll"><table><tr><th>Date</th><th class="r">Assets</th><th class="r">Liabilities</th><th class="r">Net worth</th><th></th></tr><?php foreach (array_reverse($hist) as $r): $nw=$r['assets']-$r['liabilities']; ?><tr><td><?= e($r['snap_date']) ?></td><td class="r"><?= money($r['assets']) ?></td><td class="r"><?= money($r['liabilities']) ?></td><td class="r"><?= money($nw) ?></td><td style="width:140px"><?= bar(abs($nw)/$mx*100,$nw<0?'over':'good') ?></td></tr><?php endforeach; ?></table></div><p class="note">A snapshot is saved each day you open FinTrack.</p><?php endif; page_foot();
